 public static class ThreeSnowmenIntake {
 const string Source=CatalogPreparation.Root+"/Sources/ThreeSnowmen/",Logs="Logs/ThreeSnowmen",Request="Logs/ImportThreeSnowmen.request";
 static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
 static void Require(bool ok,string message){if(!ok)throw new InvalidOperationException("Snowmen: "+message);}
 [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
 static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Install();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
 static Material Palette(){var path=Source+"SnowmanPalette.mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Simple Lit")){name="Snowmen | shared opaque palette",enableInstancing=true};m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Source+"Palette.png"));m.SetColor("_BaseColor",Color.white);m.SetColor("_SpecColor",Color.black);m.SetFloat("_Smoothness",0);m.SetFloat("_Cull",2);AssetDatabase.CreateAsset(m,path);}return m;}
 static CatalogAsset Prepare(int index,Material snow){var id="snowman-"+index.ToString("D2");var a=CatalogPreparation.Library().Find(id);if(a&&a.prefab){CatalogPreparation.RecordMetrics(a);return a;}var path=Source+"Snowman"+index.ToString("D2")+".fbx";var importer=(ModelImporter)AssetImporter.GetAtPath(path);Require(importer!=null,"missing FBX");importer.importLights=false;importer.importCameras=false;importer.importAnimation=false;importer.globalScale=1;importer.isReadable=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SnowmanPalette"),Palette());importer.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"SnowmanSnow"),snow);importer.SaveAndReimport();string title=new[]{"Classic snowman","Knit-cap snowman","Earmuff snowman"}[index-1];var draft=CatalogPreparation.Draft(title,CatalogKind.Landscape,AssetSource.ImportedModel,null,"User supplied Three_Low_Poly_Snowmen_1000_Triangles.blend, SHA256 3DD2D1DDCC66F1704554B5EB9998F664C782242FD9245E600D1B2D44E5B4EC6A. Original preserved; studio ground/cameras/lights excluded, embedded scripts never executed.");draft.id=id;draft.creationSourcePath="SourceAssets/ThreeSnowmen/Three_Low_Poly_Snowmen_1000_Triangles.blend";a=CatalogPreparation.Prepare(AssetDatabase.LoadAssetAtPath<GameObject>(path),CatalogKind.Landscape,title,1,Vector3.zero,AssetSource.ImportedModel,draft.provenance,draft);path=AssetDatabase.GetAssetPath(a.prefab);var root=PrefabUtility.LoadPrefabContents(path);
 try{var visual=root.transform.Find("VisualRoot");visual.localPosition=Vector3.zero;var raw=visual.GetChild(0);if(PrefabUtility.IsPartOfPrefabInstance(raw))PrefabUtility.UnpackPrefabInstance(PrefabUtility.GetOutermostPrefabInstanceRoot(raw.gameObject),PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var frames=raw.GetComponentsInChildren<Transform>();var by=root.transform.InverseTransformPoint(frames.Single(t=>t.name=="BasisY").position);visual.localRotation=Quaternion.FromToRotation(-by.normalized,Vector3.forward);foreach(var c in root.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c.gameObject);foreach(var r in root.GetComponentsInChildren<MeshRenderer>())r.sharedMaterial=r.name.StartsWith("SnowBody")?snow:Palette();foreach(var t in frames.Where(t=>t.name.StartsWith("Basis")))UnityEngine.Object.DestroyImmediate(t.gameObject);var bounds=CatalogValidation.BoundsOf(root);visual.localPosition-=Vector3.up*bounds.min.y;var proxy=new GameObject("Collision | snow body capsule");proxy.transform.SetParent(root.transform,false);var capsule=proxy.AddComponent<CapsuleCollider>();capsule.radius=.55f;capsule.height=Mathf.Min(2.6f,bounds.size.y);capsule.center=Vector3.up*capsule.height*.5f;PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}a.tags=new[]{"snowman","winter-decoration","static"};a.status=PreparationStatus.NeedsReview;a.visualReviewed=false;a.assumptions="Metres, grounded root, +Z face. Snow body and clothing separate; shared opaque palette and existing toon snow. Source snowman geometry is decorative and never changes snow accounting. Narrow body capsule, no runtime behavior/lights.";a.reviewNotes="Review phone readability/handling and A07 cost before Ready publication.";CatalogPreparation.RecordMetrics(a);Require(a.triangles==1000,"expected 1000 triangles: "+id+" got "+a.triangles);EditorUtility.SetDirty(a);return a;}
 static bool OverlapXZ(Bounds a,Bounds b,float margin)=>a.min.x<b.max.x+margin&&a.max.x>b.min.x-margin&&a.min.z<b.max.z+margin&&a.max.z>b.min.z-margin;
 static void Place(Scene scene,CatalogAsset[] entries,SnowField snow){var terrain=All<Terrain>(scene).Single();var wanted=new[]{new Vector3(-48,0,48),new Vector3(18,0,83),new Vector3(83,0,-18)};var roads=All<Renderer>(scene).Where(r=>r.name=="Road | asphalt").Select(r=>r.bounds).ToArray();
 for(int i=0;i<3;i++){string id="pinefall-snowman-"+(i+1).ToString("D2");if(All<CatalogPlacement>(scene).Any(p=>p.placementId==id))continue;var go=(GameObject)PrefabUtility.InstantiatePrefab(entries[i].prefab,scene);go.transform.rotation=Quaternion.LookRotation(new Vector3(-1,0,-1));var p=go.GetComponent<CatalogPlacement>();p.placementId=id;bool found=false;var blockers=All<Collider>(scene).Where(c=>c.enabled&&c.gameObject.activeInHierarchy&&!c.isTrigger&&!(c is TerrainCollider)&&!c.transform.IsChildOf(go.transform)&&!c.GetComponentInParent<SnowField>()&&!c.GetComponentInParent<MachineController>()).Select(c=>c.bounds).ToArray();var entrances=All<AssetAnchor>(scene).Where(x=>x.role==AnchorRole.Entrance).Select(x=>x.transform.position).ToArray();
 for(int n=0;n<257;n++){var at=wanted[i];if(n>0){float radius=((n-1)/16+1)*.75f;float angle=(n-1)%16*Mathf.PI*2/16;at+=new Vector3(Mathf.Cos(angle)*radius,0,Mathf.Sin(angle)*radius);}at.y=terrain.SampleHeight(at)+terrain.transform.position.y+.008f;go.transform.position=at;Physics.SyncTransforms();var b=WorldBounds(go);if(roads.Any(r=>OverlapXZ(b,r,2))||blockers.Any(x=>b.Intersects(x))||entrances.Any(e=>new Vector2(e.x-at.x,e.z-at.z).magnitude<4))continue;bool snowFree=true;for(float x=b.min.x;x<=b.max.x;x+=.5f)for(float z=b.min.z;z<=b.max.z;z+=.5f){int cell=snow.seed.grid.Index(x,z);if(cell>=0&&snow.seed.grid.depth[cell]>.004f)snowFree=false;}if(!snowFree)continue;found=true;break;}
 Require(found,"no clear residential location for "+id);PrefabUtility.RecordPrefabInstancePropertyModifications(p);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);}
 }
 static Bounds WorldBounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
 static void Preview(GameObject go,string file,Vector3 direction){var p=new PreviewRenderUtility();try{var copy=UnityEngine.Object.Instantiate(go);copy.transform.position=Vector3.zero;p.AddSingleGO(copy);foreach(var t in copy.GetComponentsInChildren<WorldSignLabel>())t.Refresh();var b=WorldBounds(copy);p.camera.orthographic=true;p.camera.orthographicSize=Mathf.Max(b.extents.x,b.extents.y)*1.3f;p.camera.nearClipPlane=.1f;p.camera.farClipPlane=300;p.camera.transform.position=b.center+direction.normalized*80;p.camera.transform.LookAt(b.center);p.camera.backgroundColor=new Color(.3f,.4f,.47f);p.camera.clearFlags=CameraClearFlags.SolidColor;p.ambientColor=Color.gray;p.lights[0].intensity=1.2f;p.lights[0].transform.rotation=p.camera.transform.rotation;p.BeginStaticPreview(new Rect(0,0,1200,800));p.Render(true);var image=p.EndStaticPreview();File.WriteAllBytes(Logs+"/"+file+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{p.Cleanup();}}
 [MenuItem("Snowglow/Asset intake/Import three snowmen")]
 public static void Install(){Require(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath,"open Pinefall");SceneValidation.Validate(scene);Directory.CreateDirectory(Logs);if(!File.Exists(Logs+"/Pinefall-before.unity"))EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before.unity",true);else if(scene.isDirty)EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-unsaved-before.unity",true);var snow=All<SnowField>(scene).Single();var original=snow.seed;var before=JsonUtility.ToJson(original.grid);var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>GlobalObjectId.GetGlobalObjectIdSlow(p).ToString(),p=>p.transform.localToWorldMatrix.ToString("R"));var tex=(TextureImporter)AssetImporter.GetAtPath(Source+"Palette.png");tex.filterMode=FilterMode.Point;tex.wrapMode=TextureWrapMode.Clamp;tex.mipmapEnabled=false;tex.textureCompression=TextureImporterCompression.Uncompressed;tex.SaveAndReimport();var entries=Enumerable.Range(1,3).Select(i=>Prepare(i,snow.palette.snow)).ToArray();Place(scene,entries,snow);Physics.SyncTransforms();var revised=UnityEngine.Object.Instantiate(original);int changed=0;for(int i=0;i<revised.grid.blocked.Length;i++){bool blocked=Physics.CheckBox(new Vector3(revised.grid.X(i),SnowField.Ground+.85f,revised.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(blocked!=revised.grid.blocked[i]){revised.grid.blocked[i]=blocked;changed++;}}if(changed>0){AssetDatabase.CreateAsset(revised,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/SnowmenSnowObstacles.asset"));snow.seed=revised;EditorUtility.SetDirty(snow);}else UnityEngine.Object.DestroyImmediate(revised);AssetDatabase.SaveAssets();SceneValidation.Validate(scene);EditorSceneManager.MarkSceneDirty(scene);Require(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);SceneValidation.Validate(scene);MechanicsChecks.Run();snow=All<SnowField>(scene).Single();var mask=snow.seed.grid.blocked;snow.seed.grid.blocked=original.grid.blocked;Require(before==JsonUtility.ToJson(snow.seed.grid),"snow quantities changed");snow.seed.grid.blocked=mask;foreach(var p in All<CatalogPlacement>(scene).Where(p=>poses.ContainsKey(GlobalObjectId.GetGlobalObjectIdSlow(p).ToString())))Require(poses[GlobalObjectId.GetGlobalObjectIdSlow(p).ToString()]==p.transform.localToWorldMatrix.ToString("R"),"existing pose changed");var placed=All<CatalogPlacement>(scene).Where(p=>(p.placementId??"").StartsWith("pinefall-snowman-")).OrderBy(p=>p.placementId).ToArray();Require(placed.Length==3&&placed.Select(p=>p.assetId).Distinct().Count()==3,"one of each required");for(int i=0;i<3;i++)Preview(placed[i].gameObject,"Snowman-"+(i+1),new Vector3(-1,.25f,-1));File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". Three catalog Needs Review variants, each 1000 triangles / two renderers; 3000 total triangles, shared palette and existing toon snow. All three placed, roads/entrances/colliders/seeded snow avoided. "+string.Join("; ",placed.Select(p=>p.placementId+" at "+p.transform.position))+". Scene saved/reopened; scene validation and 19 snow checks passed. "+changed+" obstacle flags refreshed in separate seed if needed; snow quantities and existing catalog poses unchanged. No player saves or district rebake. Three native previews written; live driving/Android/A07 performance untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));}
